import{_ as i,o as a,c as n,ai as e}from"./chunks/framework.Ai2o9gNv.js";const c=JSON.parse('{"title":"36-if-let 表达式","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/36-if-let 表达式/36-if-let 表达式.md","filePath":"仓颉入门到实战/36-if-let 表达式/36-if-let 表达式.md","lastUpdated":1736065340000,"__rawMarkdown":"# 36-if-let 表达式\\n\\n`if-let` 表达式首先对条件中 `<-` 右侧的表达式进行求值，如果此值能匹配 `<-` 左侧的模式，则执行 `if` 分支，否则执行 `else` 分支（可省略）。例如：\\n\\n```javascript\\nmain() {\\n    let result = Option<Int64>.Some(2023)\\n\\n    if (let Some(value) <- result) {\\n        println(\\"操作成功，返回值为：${value}\\")\\n    } else {\\n        println(\\"操作失败\\")\\n    }\\n}\\n```\\n\\n运行以上程序，将输出：\\n\\n```text\\n操作成功，返回值为：2023\\n```\\n\\n对于以上程序，如果将 `result` 的初始值修改为 `Option<Int64>.None`，则 `if-let` 的模式匹配会失败，将执行 `else` 分支：\\n\\n```javascript\\nmain() {\\n    let result = Option<Int64>.None\\n\\n    if (let Some(value) <- result) {\\n        println(\\"操作成功，返回值为：${value}\\")\\n    } else {\\n        println(\\"操作失败\\")\\n    }\\n}\\n```\\n\\n运行以上程序，将输出：\\n\\n```text\\n操作失败\\n```"}'),l={name:"仓颉入门到实战/36-if-let 表达式/36-if-let 表达式.md"};function t(p,s,h,k,r,d){return a(),n("div",null,[...s[0]||(s[0]=[e("",9)])])}const o=i(l,[["render",t]]);export{c as __pageData,o as default};
